module comb_mux #(parameter W = 8) (
  input  [W-1:0] a, b, c, d,
  input  [1:0]   sel,
  input  [3:0]   req,
  output reg [W-1:0] y,
  output reg [1:0]   grant,
  output             any,
  output             parity
);
  always @* begin
    case (sel)
      2'd0: y = a;
      2'd1: y = b & c;
      2'd2: y = c | d;
      default: y = a ^ d;
    endcase
  end
  always @* begin
    casez (req)
      4'b1???: grant = 2'd3;
      4'b01??: grant = 2'd2;
      4'b001?: grant = 2'd1;
      default: grant = 2'd0;
    endcase
  end
  assign any = |req;
  assign parity = ^a;
endmodule

module addsub #(parameter W = 16) (
  input  [W-1:0] a, b,
  input          sub,
  output [W:0]   y
);
  assign y = sub ? {1'b0, a} - {1'b0, b} : {1'b0, a} + {1'b0, b};
endmodule

module mul_reg #(parameter W = 6) (
  input              clk,
  input  [W-1:0]     a, b,
  output reg [2*W-1:0] p
);
  always @(posedge clk) p <= a * b;
endmodule

module macc #(parameter W = 6, parameter AW = 16) (
  input               clk, rst,
  input  [W-1:0]      a, b,
  output reg [AW-1:0] acc
);
  always @(posedge clk)
    if (rst) acc <= {AW{1'b0}};
    else     acc <= acc + a * b;
endmodule

module fsm_seqdet (
  input      clk, rst, din,
  output reg hit
);
  localparam S0 = 2'd0, S1 = 2'd1, S2 = 2'd2, S3 = 2'd3;  // detects 1101
  reg [1:0] st;
  always @(posedge clk) begin
    if (rst) begin
      st <= S0; hit <= 1'b0;
    end else begin
      hit <= 1'b0;
      case (st)
        S0: st <= din ? S1 : S0;
        S1: st <= din ? S2 : S0;
        S2: st <= din ? S2 : S3;
        S3: begin st <= din ? S1 : S0; hit <= din; end
      endcase
    end
  end
endmodule

module counter #(parameter W = 8) (
  input              clk, rst, en, up,
  output reg [W-1:0] q,
  output             tc
);
  always @(posedge clk)
    if (rst)     q <= {W{1'b0}};
    else if (en) q <= up ? q + 1'b1 : q - 1'b1;
  assign tc = up ? &q : ~|q;
endmodule

module shreg #(parameter W = 2, parameter DEPTH = 16) (
  input          clk, en,
  input  [W-1:0] d,
  output [W-1:0] q
);
  reg [W*DEPTH-1:0] sr;
  always @(posedge clk)
    if (en) sr <= {sr[W*DEPTH-W-1:0], d};
  assign q = sr[W*DEPTH-1 -: W];
endmodule

module lutram #(parameter AW = 4, parameter DW = 8) (
  input           clk, we,
  input  [AW-1:0] wa, ra,
  input  [DW-1:0] d,
  output [DW-1:0] q
);
  reg [DW-1:0] mem [0:(1<<AW)-1];
  always @(posedge clk) if (we) mem[wa] <= d;
  assign q = mem[ra];
endmodule

module bram #(parameter AW = 6, parameter DW = 16) (
  input               clk, we,
  input  [AW-1:0]     addr,
  input  [DW-1:0]     d,
  output reg [DW-1:0] q
);
  (* ram_style = "block" *) reg [DW-1:0] mem [0:(1<<AW)-1];
  always @(posedge clk) begin
    if (we) mem[addr] <= d;
    q <= mem[addr];
  end
endmodule

module ph_lane #(parameter W = 4) (
  input              clk,
  input  [W-1:0]     a, b,
  output reg [W-1:0] y
);
  always @(posedge clk) y <= (a + b) ^ {W{a[0]}};
endmodule

module param_hier #(parameter N = 3, parameter W = 4) (
  input              clk,
  input  [N*W-1:0]   a, b,
  output [N*W-1:0]   y,
  output [2*W-1:0]   z
);
  genvar i;
  generate
    for (i = 0; i < N; i = i + 1) begin : lane
      ph_lane #(.W(W)) u (.clk(clk), .a(a[i*W +: W]), .b(b[i*W +: W]), .y(y[i*W +: W]));
    end
  endgenerate
  ph_lane #(.W(2*W)) wide (.clk(clk), .a(a[2*W-1:0]), .b(b[2*W-1:0]), .y(z));
endmodule

// Legacy test: 4-bit comparator with equality and greater-than outputs.
module cmp4 (
  input  [3:0] a, b,
  output       eq,
  output       gt
);
  assign eq = (a == b)
  assign gt = (a > b);
endmodule

// Legacy test: binary counter with Gray-coded output.
module gray_counter #(parameter W = 4) (
  input              clk, rst,
  output reg [W-1:0] g
);
  reg [W-1:0] b;
  always @(posedge clk)
    if (rst) begin b <= {W{1'b0}}; g <= {W{1'b0}}; end
    else begin b <= b + 1'b1; g <= (b + 1'b1) ^ ((b + 1'b1) >> 1); end
endmodule

// Legacy test: 32-bit parity and all-ones/all-zeros detection.
// Note: expectation block in the manifest was copied from the multiplier test.
module parity32 (
  input  [31:0] x,
  output        par,
  output        ones,
  output        zeros
);
  assign par   = ^x;
  assign ones  = &x;
  assign zeros = ~|x;
endmodule

