module arst_counter #(parameter W = 4) (
  input              clk, arst, en,
  output reg [W-1:0] q
);
  always @(posedge clk or posedge arst)
    if (arst)    q <= {W{1'b0}};
    else if (en) q <= q + 1'b1;
endmodule

module mux32 (
  input  [31:0] d,
  input  [4:0]  s,
  output        y
);
  assign y = d[s];
endmodule
